function filterHostels(query){document.querySelectorAll("#hostel-list > div").forEach((item=>{item.querySelector("h2").textContent.toLowerCase().includes(query)?item.style.display="":item.style.display="none"}))}document.addEventListener("DOMContentLoaded",(()=>{fetchHostels(),document.getElementById("search").addEventListener("input",(event=>{filterHostels(event.target.value.toLowerCase())}))}));